code.C:
#include <stdio.h>
#include <string.h>

int main() {
    char s[1000];
    if (fgets(s, sizeof(s), stdin)) {
        s[strcspn(s, "\r\n")] = '\0';
        printf("%s %zu\n", s, strlen(s));
    }
    return 0;
}

